#ifndef GAUGEBOY_OBD_VIN_MODEL_DATA_H
#define GAUGEBOY_OBD_VIN_MODEL_DATA_H

/*
 * The VIN model-name table, generated by tools/make_vin_models.py from
 * NHTSA vPIC (public domain) into vin_model_data.c. Use obd_vin_model()
 * (obd_vin.h) rather than these directly. Platform-free.
 */

#include <stdint.h>

#define VIN_MODEL_FIRST_YEAR 1996
#define VIN_MODEL_OPEN_YEAR  255    /* year_to: no end year */

typedef struct {
    const char *make;        /* vPIC make, e.g. "Subaru" */
    const char *model;       /* e.g. "Ascent" */
} vin_model_name_t;

typedef struct {
    uint8_t year_from;       /* model years, minus VIN_MODEL_FIRST_YEAR */
    uint8_t year_to;
    uint16_t keys;           /* index into vin_model_keys */
    uint16_t name;           /* index into vin_model_names */
} vin_model_rule_t;

typedef struct {
    char wmi[7];             /* 3 characters, or 6 when position 3 is '9' */
    uint32_t first;          /* first rule in vin_model_rules */
    uint32_t count;          /* rules, first match wins */
} vin_model_wmi_t;

extern const vin_model_name_t vin_model_names[];
extern const char *const vin_model_keys[];
extern const vin_model_rule_t vin_model_rules[];
extern const vin_model_wmi_t vin_model_wmis[];   /* sorted by wmi */
extern const int vin_model_name_count;
extern const int vin_model_key_count;
extern const int vin_model_rule_count;
extern const int vin_model_wmi_count;

#endif
